// ui_filter_bar.js

const STATE = require('STATE')
const statedb = STATE(__filename)
const { get } = statedb(fallback_module)
const net = require('net_helper')

module.exports = ui_filter_bar

async function ui_filter_bar (opts, invite) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = {
    style: inject,
    icons: iconject
  }

  const { io, _ } = net(id)

  io.on = {
    up: io_up()
  }

  if (invite) io.accept(invite)

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="ui-filter-bar">
      <button class="filter-btn icon-btn btn-filter"></button>
      <div class="filter-scroll-container">
        <button class="filter-item active" data-view="components">Loaders</button>
        <button class="filter-item" data-view="components">Check Box</button>
        <button class="filter-item" data-view="components">Toggle button</button>
        <button class="filter-item" data-view="components">Cards</button>
        <button class="filter-item" data-view="components">Buttons</button>
        <button class="filter-item" data-view="components">Input field</button>
        <button class="filter-item" data-view="my_saves">My Saves</button>
      </div>
    </div>
  `

  const sheet = new CSSStyleSheet()
  shadow.adoptedStyleSheets = [sheet]

  const btn_filter = shadow.querySelector('.btn-filter')
  const scroll_container = shadow.querySelector('.filter-scroll-container')

  // 2. Transformed visibility event handling into an explicit item property assignment
  btn_filter.onclick = () => {
    scroll_container.classList.toggle('hidden')
  }

  // 3. Transformed routing interaction pattern into item property configuration
  scroll_container.onclick = (e) => {
    const item = e.target.closest('.filter-item')
    if (!item) return

    shadow.querySelectorAll('.filter-item').forEach(el => el.classList.remove('active'))
    item.classList.add('active')

    const targetView = item.getAttribute('data-view')

    _.up('show_view', { view: targetView }, {})
  }

  await sdb.watch(onbatch)


  return el

  async function onbatch (batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(
        paths.map(path => drive.get(path).then(file => file.raw))
      )

      const handler = on[type] || (() => {})
      handler({ data })
    }
  }

  function inject ({ data }) {
    sheet.replaceSync(data[0])
  }

  function iconject ({ data }) {
    if (btn_filter) btn_filter.innerHTML = data[0] || ''
  }

  function io_up () {
    return function onmessage (msg) {
      console.log('[ui_filter_bar] message from parent ->', msg)
    }
  }
}

function fallback_module () {
  return {
    api: fallback_instance,
    _: { net_helper: { $: '' } }
  }
  function fallback_instance () {
    return {
      _: {
        net_helper: { 0: '' },
        ui_filter_bar: { mapping: { style: 'style', icons: 'icons' } }
      },
      drive: {
        'icons/filter.svg': { $ref: 'filter.svg' },
        'style/ui_filter_bar.css': { $ref: 'ui_filter_bar.css' }
      }
    }
  }
}